import re, sys
src = open(sys.argv[1]).read()
funcs = re.split(r'void (test_integer__\w+)\(void\)', src)
for i in range(1, len(funcs), 2):
    name, body = funcs[i], funcs[i+1]
    lines = body.splitlines()
    rows = []
    for j, l in enumerate(lines):
        m = re.search(r'cl_assert\((!?)git__multiply_int64_overflow\(&result, INT64_C\(([-0-9a-fx]+)\), INT64_C\(([-0-9a-fx]+)\)\)\)', l)
        if m:
            rows.append([m.group(1) == '!', m.group(2), m.group(3), None])
            continue
        m = re.search(r'cl_assert_equal_i\(result, INT64_C\(([-0-9a-fx]+)\)\)', l)
        if m:
            rows[-1][3] = m.group(1)
    print(name, len(rows), sum(1 for r in rows if r[3]))
    def lit(s):
        neg = s.startswith('-'); s = s.lstrip('-')
        v = int(s, 16)
        if neg and v == 1 << 63: return 'i64::MIN'
        return ('-' if neg else '') + '0x' + format(v, 'x')
    out = open(sys.argv[2] + '/' + name + '.rs', 'w')
    for ok, a, b, r in rows:
        if ok:
            out.write('(%s, %s, %s),\n' % (lit(a), lit(b), ('Some(%s)' % lit(r)) if r else 'None'))
        else:
            out.write('(%s, %s),\n' % (lit(a), lit(b)))
EOF
